-- Ejecutar en Supabase > SQL Editor, una sola vez.
create table if not exists public.trips (
 id uuid primary key,
 data jsonb not null default '{}'::jsonb,
 updated_at timestamptz not null default now()
);
create table if not exists public.trip_members (
 trip_id uuid not null references public.trips(id) on delete cascade,
 user_id uuid not null references auth.users(id) on delete cascade,
 primary key(trip_id,user_id)
);
create or replace function public.set_trip_updated_at() returns trigger language plpgsql as $$
begin new.updated_at=clock_timestamp(); return new; end $$;
drop trigger if exists trg_trip_updated_at on public.trips;
create trigger trg_trip_updated_at before update on public.trips for each row execute function public.set_trip_updated_at();
alter table public.trips enable row level security;
alter table public.trip_members enable row level security;
revoke all on public.trips from anon;
revoke all on public.trip_members from anon;
grant select,update on public.trips to authenticated;
create policy "members read trip" on public.trips for select to authenticated
 using (exists(select 1 from public.trip_members m where m.trip_id=id and m.user_id=(select auth.uid())));
create policy "members update trip" on public.trips for update to authenticated
 using (exists(select 1 from public.trip_members m where m.trip_id=id and m.user_id=(select auth.uid())))
 with check (exists(select 1 from public.trip_members m where m.trip_id=id and m.user_id=(select auth.uid())));
